!!this.item.item && this.item.item.salableVariationCount == 1 && this.item.prices.graduatedPrices.length > 1 && App.config.item.enableGraduatedPrices;\n        },\n\n        itemSetPrice()\n        {\n            return this.$options.filters.currency(\n                this.item.prices.default.price.value,\n                this.item.prices.default.currency\n            );\n        },\n\n        urlWithVariationId()\n        {\n            return !this.$ceres.config.item.showPleaseSelect || this.$ceres.initialPleaseSelect == 0 || this.forceUrlWithVariationId;\n        },\n\n        hasCrossPrice() {\n            const hasRrpPrice = !!this.item.prices.rrp &&\n                this.item.prices.rrp.unitPrice.value > this.item.prices.default.unitPrice.value;\n\n            const hasBeforePrice = !!this.item.prices.specialOffer &&\n                !!this.item.prices.default &&\n                this.item.prices.default.unitPrice.value > this.item.prices.specialOffer.unitPrice.value;\n\n            return hasRrpPrice || hasBeforePrice;\n        },\n\n        ...mapState({\n            showNetPrices: state => state.basket.showNetPrices\n        })\n    }\n}\n</script>\n","<template>\n    <div v-if=\"hasLabel || isBundle || isSet\" class=\"special-tags p-2\">\n        \n        <span v-if=\"hasLabel\" class=\"badge\" :class=\"tagClass\">\n            {{ label }}\n        </span>\n\n        <span v-else-if=\"isBundle\" :class=\"tagClasses.itemBundle\">\n            {{ $translate(\"Ceres::Template.itemBundle\") }}\n        </span>\n\n        <span v-else-if=\"isSet\" :class=\"tagClasses.itemSet\">\n            {{ $translate(\"Ceres::Template.itemSet\") }}\n        </span>\n\n    </div>\n</template>\n\n<script>\nimport { isNullOrUndefined, isDefined } from \"../../helper/utils\";\n\nexport default {\n\n    name: \"item-store-special\",\n\n    props: [\n        \"storeSpecial\",\n        \"recommendedRetailPrice\",\n        \"variationRetailPrice\",\n        \"specialOfferPrice\",\