;AACzB;AACA;AACA,qBAAqB;AACrB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,4BAA4B;AAC5B,mBAAmB;AACnB;AACA,gCAAgC,+BAA+B;AAC/D;AACA;AACA;AACA;AACA,sCAAsC,sBAAsB;AAC5D;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,0BAA0B,sBAAsB;AAChD;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,+BAA+B;AAC/B;AACA;AACA;AACA,iCAAiC;AACjC;AACA;AACA;AACA,yBAAyB;AACzB;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA,iBAAiB;AACjB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,4BAA4B,wCAAwC;AACpE;AACA;AACA;AACA;AACA;AACA;AACA,eAAe;AACf;AACA;AACA;AACA;AACA,aAAa;AACb;AACA;AACA;AACA;AACA;AACA,0BAA0B;AAC1B,iBAAiB;AACjB;AACA;AACA;AACA,0BAA0B,yCAAyC;AACnE,4BAA4B,+BAA+B;AAC3D;AACA;AACA;AACA;AACA,kCAAkC,sBAAsB;AACxD;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,8BAA8B,gCAAgC;AAC9D,6BAA6B,kCAAkC;AAC/D;AACA;AACA;AACA;AACA;AACA,8BAA8B,wBAAwB;AACtD;AACA;AACA;AACA;AACA;AACA;AACA,qBAAqB;AACrB,8BAA8B,6BAA6B;AAC3D;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,iBAAiB;AACjB;AACA;AACA;AACA;AACA;AACA,eAAe;AACf;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AC1XA;AAAA;AAAA;AAAA;AAAgG;AAC3B;AACL;;;AAGhE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,uFAAM;AACR,EAAE,4FAAM;AACR,EAAE,qGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAyM,CAAgB,qPAAG,EAAC,C;;;;;;;;;;;;ACA7N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAqG;AAC3B;AACL;;;AAGrE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,4FAAM;AACR,EAAE,iGAAM;AACR,EAAE,0GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA8M,CAAgB,0PAAG,EAAC,C;;;;;;;;;;;;ACAlO;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAoG;AAC3B;AACL;;;AAGpE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,2FAAM;AACR,EAAE,gGAAM;AACR,EAAE,yGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA6M,CAAgB,yPAAG,EAAC,C;;;;;;;;;;;;ACAjO;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-5.js","sourcesContent":["<template>\n    <div class=\"order-property-slider mb-3\" v-if=\"renderOrderPropertyList\">\n        <div class=\"order-property-slider-inner\" :style=\"{transform: 'translateX(-' + (activeSlide * 100) + '%)'}\">\n            <div v-for=\"(propertyGroup, index) in sortedGroupedProperties\" :class=\"{'active': index === activeSlide}\" :key=\"index\">\n                <order-property-list-group\n                    :padding-classes=\"paddingClasses\"\n                    :padding-inline-styles=\"paddingInlineStyles\"\n                    :key=\"propertyGroup.id\"\n                    :property-group=\"propertyGroup\">\n                </order-property-list-group>\n            </div>\n        </div>\n\n        <div class=\"order-property-slider-controls\" :class=\"paddingClasses\" :style=\"paddingInlineStyles\" v-if=\"sortedGroupedProperties.length > 1\">\n            <div\n                class=\"btn shadow-none\"\n                @click=\"slideTo(activeSlide - 1)\"\n                :class=\"{'btn-primary': activeSlide > 0, 'btn-secondary disabled': activeSlide === 0}\"\n                tabindex=\"0\"\n                data-testing=\"order-property-previous-slide\">\n                <span class=\"fa fa-chevron-left\"></span>\n            </div>\n\n            <div class=\"slider-nav\">\n                <span v-for=\"(propertyGroup, index) in sortedGroupedProperties\"\n                      :class=\"{ 'active': index === activeSlide, 'highlight': !touchedSlides[index], 'error': propertyGroup.hasError }\"\n                      @click=\"slideTo(index)\"\n                      :key=\"index\"\n                      v-tooltip\n                      data-toggle=\"tooltip\"\n                      data-placement=\"top\"\n                      :title=\"propertyGroup.group ? propertyGroup.group.names.name : $translate('Ceres::Template.singleItemPropertiesWithoutGroup')\">\n                </span>\n            </div>\n\n            <div\n                class=\"btn float-right shadow-none\"\n                @click=\"slideTo(activeSlide + 1)\"\n                :class=\"{'btn-primary': activeSlide < sortedGroupedProperties.length - 1, 'btn-secondary disabled': activeSlide >= sortedGroupedProperties.length - 1 }\"\n                tabindex=\"0\"\n                data-testing=\"order-property-next-slide\">\n                <span class=\"fa fa-chevron-right\"></span>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport OrderPropertyListGroup from \"./OrderPropertyListGroup.vue\";\n\nexport default {\n\n    components:\n    {\n        \"order-property-list-group\": OrderPropertyListGroup\n    },\n\n    props:\n    {\n        paddingClasses:\n        {\n            type: String,\n            default: null\n        },\n        paddingInlineStyles:\n        {\n            type: String,\n            default: null\n        },\n    },\n\n    inject: {\n        itemId: {\n            default: null\n        }\n    },\n\n    data()\n    {\n        return {\n            activeSlide: 0,\n            touchedSlides: { 0: true }\n        };\n    },\n\n    computed:\n    {\n        sortedGroupedProperties()\n        {\n            const groupedProperties = JSON.parse(JSON.stringify(this.variationGroupedProperties));\n\n            for (const group of groupedProperties)\n            {\n                this.sortGroupProperties(group);\n            }\n\n            return this.getSortedGroups(groupedProperties);\n        },\n\n        missingPropertyGroupIds()\n        {\n            if (this.variationMarkInvalidProperties)\n            {\n                return [...new Set(this.variationMissingProperties.map(property => property.group && property.group.id))];\n            }\n\n            return [];\n        },\n\n        variationGroupedProperties()\n        {\n            return this.$store.getters[`${this.itemId}/variationGroupedProperties`];\n        },\n\n        renderOrderPropertyList()\n        {\n            return (this.$store.getters[`${this.itemId}/currentItemVariation`].filter.isSalable && this.variationGroupedProperties.length) || App.isShopBuilder;\n        },\n\n        variationMissingProperties()\n        {\n            return this.$store.getters[`${this.itemId}/variationMissingProperties`];\n        },\n\n        variationMarkInvalidProperties() {\n            const currentVariation = this.$store.getters[`${this.itemId}/currentItemVariation`];\n            return currentVariation && currentVariation.variationMarkInvalidProperties;\n        }\n    },\n\n    methods:\n    {\n        sortGroupProperties(group)\n        {\n            return group.properties.sort((prev, current) =>\n            {\n                if (prev.position > current.position)\n                {\n                    return 1;\n                }\n                if (prev.position < current.position)\n                {\n                    return -1;\n                }\n\n                return 0;\n            });\n        },\n\n        getSortedGroups(groups)\n        {\n            for (const group of groups)\n            {\n                const lowestPosition = group.properties.reduce((prev, current) => (prev.position < current.position) ? prev : current);\n\n                group.lowestPosition = lowestPosition.position;\n\n                const groupId = group.group ? group.group.id : null;\n\n                if (this.variationMarkInvalidProperties && this.missingPropertyGroupIds.includes(groupId))\n                {\n                    group.hasError = true;\n                }\n            }\n\n            return groups.sort((prev, current) =>\n            {\n                if (prev.lowestPosition > current.lowestPosition)\n                {\n                    return 1;\n                }\n                if (prev.lowestPosition < current.lowestPosition)\n                {\n                    return -1;\n                }\n\n                return 0;\n            });\n        },\n\n        slideTo(position)\n        {\n            if (position >= 0 && position < this.sortedGroupedProperties.length)\n            {\n                this.activeSlide = position;\n                this.touchedSlides[this.activeSlide] = true;\n            }\n        }\n    }\n}\n</script>\n","<template>\n    <div>\n        <div v-if=\"isShownOnItemPageCount\">\n            <div v-if=\"propertyGroup.group\" :class=\"paddingClasses\" :style=\"paddingInlineStyles\">\n                <div class=\"h4\">\n                    {{ propertyGroup.group.names.name }}:\n                </div>\n                <p class=\"text-muted text-wrap\">\n                    {{ propertyGroup.group.names.description }}\n                </p>\n            </div>\n\n            <div v-for=\"property in propertyGroup.properties\" :key=\"property.id\" :class=\"paddingClasses\" :style=\"paddingInlineStyles\">\n                <order-property-list-item v-if=\"property.isShownOnItemPage\" :group=\"propertyGroup.group\" :property=\"property\"></order-property-list-item>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport OrderPropertyListItem from \"./OrderPropertyListItem.vue\";\n\nexport default {\n\n    components:\n    {\n        OrderPropertyListItem\n    },\n\n    props:\n    {\n        paddingClasses:\n        {\n            type: String,\n            default: null\n        },\n        paddingInlineStyles:\n        {\n            type: String,\n            default: null\n        },\n        propertyGroup: Object\n    },\n\n    computed:\n    {\n        isShownOnItemPageCount()\n        {\n            const properties = this.propertyGroup.properties.filter(property => property.isShownOnItemPage);\n\n            return properties.length;\n        }\n    }\n}\n</script>\n","<template>\n    <div>\n        <div v-if=\"inputType === 'text' || inputType === 'float' || inputType === 'int'\" class=\"input-unit order-property-input\" :class=\"{ 'active': property.value, 'error': hasError }\" data-validate=\"text\">\n            <input\n                type=\"text\"\n                @input=\"onInputValueChanged($event.target.value)\"\n                v-model=\"inputValue\"\n                v-tooltip\n                data-toggle=\"tooltip\"\n                :title=\"property.names.description\"\n                :data-testing=\"'order-property-input-' + inputType\">\n            <label class=\"d-flex\">\n                <span class=\"text-truncate\">{{ property.names.name }}</span>\n                <strong class=\"ml-1\" v-if=\"surcharge > 0\">(+ {{ surcharge | currency }}) *</strong>\n            </label>\n        </div>\n\n        <div v-else-if=\"inputType === 'checkbox' || inputType === 'radio'\" class=\"form-check\">\n            <input v-if=\"inputType === 'checkbox'\"\n                   type=\"checkbox\"\n                   :name=\"group ? group.id : 'check' + _uid\"\n                   :id=\"'check' + _uid\"\n                   :value=\"property.id\"\n                   :checked=\"property.value\"\n                   @change=\"onInputValueChanged($event.target.checked)\"\n                   class=\"form-check-input\"\n                   data-testing=\"order-property-input-checkbox\">\n            <input v-else\n                   type=\"radio\"\n                   :name=\"group ? group.id : 'check' + _uid\"\n                   :id=\"'check' + _uid\"\n                   :value=\"property.id\"\n                   @change=\"onInputValueChanged($event.target.value)\"\n                   class=\"form-check-input\"\n                   :checked=\"property.value\"\n                   data-testing=\"order-property-input-radio\">\n\n            <label class=\"form-check-label text-appearance d-flex\"\n                   :for=\"'check' + _uid\"\n                   :class=\"{ 'text-danger': hasError }\"\n                   v-tooltip data-toggle=\"tooltip\"\n                   :title=\"property.